const mimes={'.html':'text/html; charset=utf-8','.css':'text/css','.js':'application/javascript','.json':'application/json','.svg':'image/svg+xml','.png':'image/png'};
async function serve(root){const base=resolve(root);const s=createServer(async(req,res)=>{try{const pathname=decodeURIComponent(new URL(req.url,'http://localhost').pathname);let file=resolve(base,'.'+pathname);if(file!==base&&!file.startsWith(base+'/')){res.writeHead(403).end();return;}const meta=await stat(file);if(meta.isDirectory())file=join(file,'index.html');const data=await readFile(file);res.writeHead(200,{'Content-Type':mimes[extname(file)]||'application/octet-stream','X-Robots-Tag':'noindex, nofollow','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'; worker-src 'self' blob:"});res.end(data);}catch{res.writeHead(404).end('Not found');}});await new Promise(r=>s.listen(0,'127.0.0.1',r));return {server:s,origin:'http://127.0.0.1:'+s.address().port};}
const pub=await serve('dist'),priv=await serve('dist-workspace');let browser;
